changeSet.sql:
UPDATE parser SET description = 'Titulaires actuels et sortis depuis moins de 12 mois de fonctions PEP à titulaire unique sans source officielle exploitable : chef d''état-major de la Marine (catégorie FR-f) et secrétaire général du Conseil constitutionnel (catégorie FR-d)', parameters = '{"endpoint": "https://query.wikidata.org/sparql", "positions": "Q2961994 Q59156405", "monthsAfterEnd": "12"}', notes = 'Complète fr_pep_army (la page du CEMM sur defense.gouv.fr présente encore l''amiral Vaujour, remplacé le 15/07/2026) et fr_pep_constitutional_council (le site ne nomme pas le secrétaire général). Ajouter une fonction : son QID dans le paramètre positions. Données collaboratives, à contrôler avec le décret au Journal officiel.' WHERE dataset_name = 'fr_pep_wikidata_positions';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Secrétaire général du Conseil constitutionnel en fonction (Catherine Leroy depuis le 16/04/2026 en novembre 2026) et sorti depuis moins de 12 mois, d''après Wikidata.', 'Le président et les membres viennent de fr_pep_constitutional_council. Source collaborative, non officielle : à rapprocher du décret de nomination au Journal officiel.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'FR-d' AND f.label = 'Président, membre ou secrétaire général du Conseil constitutionnel' AND p.dataset_name = 'fr_pep_wikidata_positions' AND NOT EXISTS (SELECT 1 FROM pep_function_parser x WHERE x.function_id = f.id AND x.parser_id = p.id);
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id SET l.gaps = 'Le secrétaire général n''est pas nommé sur le site : il vient de fr_pep_wikidata_positions (Wikidata).' WHERE p.dataset_name = 'fr_pep_constitutional_council' AND f.label = 'Président, membre ou secrétaire général du Conseil constitutionnel';
